39	/// Slice-level batched RMSNorm over `rows` rows of `dim`: same
40	/// `flashinfer::norm::RMSNorm` template as [`rms_norm_into`] with
41	/// batch_size=rows (one CTA per row), so each row is bit-identical to the
42	/// single-row launch. For callers whose buffers live in a persistent decode
43	/// arena rather than owned `HiddenStates`.
44	pub fn rms_norm_rows_into(
45	    ctx: &DeviceContext,
46	    x: &CudaSlice<bf16>,
47	    weight: &DeviceVec,
48	    eps: f32,
49	    dim: usize,
50	    rows: usize,
51	    out: &mut CudaSlice<bf16>,
52	) -> Result<()> {
53	    ensure!(rows > 0 && dim > 0, "rms_norm_rows needs positive rows/dim");
54	    ensure!(
55	        x.len() >= rows * dim && out.len() >= rows * dim,
56	        "rms_norm_rows buffers too small for {rows}x{dim}: x {}, out {}",
57	        x.len(),
58	        out.len()
59	    );
60	    ensure!(
61	        weight.len == dim,
62	        "rms_norm_rows weight len {} != dim {dim}",
63	        weight.len
64	    );
65	    let (x_ptr, _gx) = x.device_ptr(&ctx.stream);
66	    let (w_ptr, _gw) = weight.data.device_ptr(&ctx.stream);
67	    let (out_ptr, _go) = out.device_ptr_mut(&ctx.stream);
68	    unsafe {
69	        ffi::rms_norm_batched_cuda(
70	            x_ptr as *const ffi::Half,
71	            w_ptr as *const ffi::Half,
72	            out_ptr as *mut ffi::Half,
73	            dim as i32,
74	            rows as i32,
75	            eps,
76	            crate::tensor::active_cu_stream(ctx),
77	        );
78	    }
79	    Ok(())
80	}
