82	/// RMSNorm (allocating)
83	pub fn rms_norm(
84	    ctx: &DeviceContext,
85	    x: &DeviceVec,
86	    weight: &DeviceVec,
87	    eps: f32,
88	) -> Result<DeviceVec> {
89	    let mut out = DeviceVec::zeros(ctx, x.len)?;
90	    rms_norm_into(ctx, x, weight, eps, &mut out)?;
91	    Ok(out)
92	}
