94	/// LayerNorm (with bias) of a single bf16 vector `[dim]` — GLM5.2 DSA indexer
95	/// k_norm (eps=1e-6, has bias). Wraps `flashinfer::norm::LayerNorm` (same
96	/// vendored template that `rms_norm_cuda` wraps). Unlike RMSNorm, LayerNorm
97	/// subtracts the mean and applies a per-element bias. gamma/beta are f32
98	/// (FlashInfer's LayerNorm template requires f32 weight types).
99	pub fn layer_norm_into(
100	    ctx: &DeviceContext,
101	    x: &CudaSlice<bf16>,
102	    gamma: &CudaSlice<f32>,
103	    beta: &CudaSlice<f32>,
104	    eps: f32,
105	    dim: usize,
106	    rows: usize,
107	    out: &mut CudaSlice<bf16>,
108	) -> Result<()> {
109	    ensure!(rows > 0 && dim > 0, "layer_norm needs positive rows/dim");
110	    ensure!(
111	        x.len() >= rows * dim && out.len() >= rows * dim,
112	        "layer_norm x/out too small for {rows}x{dim}: x {}, out {}",
113	        x.len(),
114	        out.len()
115	    );
116	    ensure!(gamma.len() >= dim, "layer_norm gamma too small");
117	    ensure!(beta.len() >= dim, "layer_norm beta too small");
118	    let (x_ptr, _gx) = x.device_ptr(&ctx.stream);
119	    let (g_ptr, _gg) = gamma.device_ptr(&ctx.stream);
120	    let (b_ptr, _gb) = beta.device_ptr(&ctx.stream);
121	    let (o_ptr, _go) = out.device_ptr_mut(&ctx.stream);
122	    let result = unsafe {
123	        ffi::layer_norm_cuda(
124	            x_ptr as *const ffi::Half,
125	            g_ptr as *const f32,
126	            b_ptr as *const f32,
127	            o_ptr as *mut ffi::Half,
128	            dim as i32,
129	            rows as i32,
130	            eps,
131	            ctx.stream.cu_stream(),
132	        )
133	    };
134	    result
135	        .result()
136	        .map_err(|err| anyhow::anyhow!("GLM5.2 LayerNorm launch failed: {err}"))
137	}
