139	/// Fused add + RMSNorm: hidden += residual; out = rms_norm(hidden, weight)
140	/// Saves one global read of hidden compared to separate add + rms_norm.
141	pub fn fused_add_rms_norm_into(
142	    ctx: &DeviceContext,
143	    hidden: &mut DeviceVec,
144	    residual: &DeviceVec,
145	    weight: &DeviceVec,
146	    eps: f32,
147	    out: &mut DeviceVec,
148	) -> Result<()> {
149	    assert_eq!(hidden.len, residual.len);
150	    assert_eq!(hidden.len, out.len);
151	    let (h_ptr, _gh) = hidden.data.device_ptr_mut(&ctx.stream);
152	    let (r_ptr, _gr) = residual.data.device_ptr(&ctx.stream);
153	    let (w_ptr, _gw) = weight.data.device_ptr(&ctx.stream);
154	    let (o_ptr, _go) = out.data.device_ptr_mut(&ctx.stream);
155	    unsafe {
156	        ffi::fused_add_rms_norm_cuda(
157	            h_ptr as *mut ffi::Half,
158	            r_ptr as *const ffi::Half,
159	            w_ptr as *const ffi::Half,
160	            o_ptr as *mut ffi::Half,
161	            hidden.len as i32,
162	            eps,
163	            crate::tensor::active_cu_stream(ctx),
164	        );
165	    }
166	    Ok(())
167	}
