169	/// Two RMSNorms of the same input in one launch: `out_a = rms(x) * weight_a *
170	/// scale_a` and `out_b = rms(x) * weight_b`, each bitwise what its standalone
171	/// operations produce. The norms share one reduction, and the input is read
172	/// twice instead of four times.
173	#[allow(clippy::too_many_arguments)]
174	pub fn rms_norm_batch_dual_into(
175	    ctx: &DeviceContext,
176	    x: &HiddenStates,
177	    weight_a: &DeviceVec,
178	    weight_b: &DeviceVec,
179	    eps: f32,
180	    scale_a: f32,
181	    out_a: &mut HiddenStates,
182	    out_b: &mut HiddenStates,
183	) -> Result<()> {
184	    const OP: &str = "rms_norm_batch_dual_into";
185	    ensure!(
186	        x.hidden_dim > 0 && x.seq_len > 0,
187	        "{OP} dimensions must be non-zero"
188	    );
189	    ensure!(weight_a.len == x.hidden_dim, "{OP} weight_a len mismatch");
190	    ensure!(weight_b.len == x.hidden_dim, "{OP} weight_b len mismatch");
191	    ensure!(
192	        weight_a.data.len() >= x.hidden_dim,
193	        "{OP} weight_a backing too small"
194	    );
195	    ensure!(
196	        weight_b.data.len() >= x.hidden_dim,
197	        "{OP} weight_b backing too small"
198	    );
199	    ensure!(
200	        out_a.hidden_dim == x.hidden_dim && out_a.seq_len == x.seq_len,
201	        "{OP} out_a shape mismatch"
202	    );
203	    ensure!(
204	        out_b.hidden_dim == x.hidden_dim && out_b.seq_len == x.seq_len,
205	        "{OP} out_b shape mismatch"
206	    );
207	    ensure!(scale_a.is_finite(), "{OP} scale_a must be finite");
208	    x.checked_extent("rms_norm_batch_dual_into x")?;
209	    out_a.checked_extent("rms_norm_batch_dual_into out_a")?;
210	    out_b.checked_extent("rms_norm_batch_dual_into out_b")?;
211	    let hidden_dim = super::checked_i32(x.hidden_dim, "rms_norm_batch_dual_into hidden_dim")?;
212	    let seq_len = super::checked_i32(x.seq_len, "rms_norm_batch_dual_into seq_len")?;
213	    let (x_ptr, _gx) = x.data.device_ptr(&ctx.stream);
214	    let (wa_ptr, _ga) = weight_a.data.device_ptr(&ctx.stream);
215	    let (wb_ptr, _gb) = weight_b.data.device_ptr(&ctx.stream);
216	    let (oa_ptr, _goa) = out_a.data.device_ptr_mut(&ctx.stream);
217	    let (ob_ptr, _gob) = out_b.data.device_ptr_mut(&ctx.stream);
218	    let result = unsafe {
219	        ffi::rms_norm_batched_dual_cuda(
220	            x_ptr as *const ffi::Half,
221	            wa_ptr as *const ffi::Half,
222	            wb_ptr as *const ffi::Half,
223	            oa_ptr as *mut ffi::Half,
224	            ob_ptr as *mut ffi::Half,
225	            hidden_dim,
226	            seq_len,
227	            eps,
228	            scale_a,
229	            crate::tensor::active_cu_stream(ctx),
230	        )
231	    };
232	    result.result()?;
233	    Ok(())
234	}
