298	/// The attention epilogue's norm pair in one launch:
299	/// `residual_out = bf16(rms_norm(x, weight_post) + res_in)` then
300	/// `out = rms_norm(residual_out, weight_pre)`, bitwise what the separate
301	/// norm and [`fused_add_rms_norm_round_batch_into`] produce.
302	#[allow(clippy::too_many_arguments)]
303	pub fn rms_norm_add_rms_norm_round_batch_into(
304	    ctx: &DeviceContext,
305	    x: &HiddenStates,
306	    weight_post: &DeviceVec,
307	    res_in: &HiddenStates,
308	    weight_pre: &DeviceVec,
309	    eps: f32,
310	    residual_out: &mut HiddenStates,
311	    out: &mut HiddenStates,
312	) -> Result<()> {
313	    const OP: &str = "rms_norm_add_rms_norm_round_batch_into";
314	    ensure!(
315	        x.hidden_dim > 0 && x.seq_len > 0,
316	        "{OP} dimensions must be non-zero"
317	    );
318	    ensure!(
319	        weight_post.len == x.hidden_dim,
320	        "{OP} weight_post len mismatch"
321	    );
322	    ensure!(
323	        weight_pre.len == x.hidden_dim,
324	        "{OP} weight_pre len mismatch"
325	    );
326	    ensure!(
327	        weight_post.data.len() >= x.hidden_dim,
328	        "{OP} weight_post backing too small"
329	    );
330	    ensure!(
331	        weight_pre.data.len() >= x.hidden_dim,
332	        "{OP} weight_pre backing too small"
333	    );
334	    ensure!(
335	        res_in.hidden_dim == x.hidden_dim && res_in.seq_len == x.seq_len,
336	        "{OP} res_in shape mismatch"
337	    );
338	    ensure!(
339	        residual_out.hidden_dim == x.hidden_dim && residual_out.seq_len == x.seq_len,
340	        "{OP} residual_out shape mismatch"
341	    );
342	    ensure!(
343	        out.hidden_dim == x.hidden_dim && out.seq_len == x.seq_len,
344	        "{OP} out shape mismatch"
345	    );
346	    x.checked_extent("rms_norm_add_rms_norm_round_batch_into x")?;
347	    res_in.checked_extent("rms_norm_add_rms_norm_round_batch_into res_in")?;
348	    residual_out.checked_extent("rms_norm_add_rms_norm_round_batch_into residual_out")?;
349	    out.checked_extent("rms_norm_add_rms_norm_round_batch_into out")?;
350	    let hidden_dim = super::checked_i32(
351	        x.hidden_dim,
352	        "rms_norm_add_rms_norm_round_batch_into hidden_dim",
353	    )?;
354	    let seq_len = super::checked_i32(x.seq_len, "rms_norm_add_rms_norm_round_batch_into seq_len")?;
355	    let (x_ptr, _gx) = x.data.device_ptr(&ctx.stream);
356	    let (wp_ptr, _gwp) = weight_post.data.device_ptr(&ctx.stream);
357	    let (r_ptr, _gr) = res_in.data.device_ptr(&ctx.stream);
358	    let (wq_ptr, _gwq) = weight_pre.data.device_ptr(&ctx.stream);
359	    let (ro_ptr, _gro) = residual_out.data.device_ptr_mut(&ctx.stream);
360	    let (o_ptr, _go) = out.data.device_ptr_mut(&ctx.stream);
361	    let result = unsafe {
362	        ffi::rms_norm_add_rms_norm_round_batched_cuda(
363	            x_ptr as *const ffi::Half,
364	            wp_ptr as *const ffi::Half,
365	            r_ptr as *const ffi::Half,
366	            wq_ptr as *const ffi::Half,
367	            ro_ptr as *mut ffi::Half,
368	            o_ptr as *mut ffi::Half,
369	            hidden_dim,
370	            seq_len,
371	            eps,
372	            crate::tensor::active_cu_stream(ctx),
373	        )
374	    };
375	    result.result()?;
376	    Ok(())
377	}
