504	/// Slice-level twin of [`fused_add_rms_norm_round_batch_into`] — same kernel
505	/// — for callers whose buffers live in a persistent decode arena rather than
506	/// owned `HiddenStates`: `hidden += residual` (sum rounded to bf16), then
507	/// `out = rms_norm(hidden, weight)` over `seq_len` rows of `hidden_dim`.
508	pub fn fused_add_rms_norm_round_into(
509	    ctx: &DeviceContext,
510	    hidden: &mut CudaSlice<bf16>,
511	    residual: &CudaSlice<bf16>,
512	    weight: &DeviceVec,
513	    eps: f32,
514	    hidden_dim: usize,
515	    seq_len: usize,
516	    out: &mut CudaSlice<bf16>,
517	) -> Result<()> {
518	    let n = hidden_dim * seq_len;
519	    ensure!(
520	        hidden.len() >= n && residual.len() >= n && out.len() >= n,
521	        "fused_add_rms_norm_round_into buffers too small for {seq_len}x{hidden_dim}: hidden {}, residual {}, out {}",
522	        hidden.len(),
523	        residual.len(),
524	        out.len()
525	    );
526	    ensure!(
527	        weight.len == hidden_dim,
528	        "fused_add_rms_norm_round_into weight len {} != hidden_dim {hidden_dim}",
529	        weight.len
530	    );
531	    let (h_ptr, _gh) = hidden.device_ptr_mut(&ctx.stream);
532	    let (r_ptr, _gr) = residual.device_ptr(&ctx.stream);
533	    let (w_ptr, _gw) = weight.data.device_ptr(&ctx.stream);
534	    let (o_ptr, _go) = out.device_ptr_mut(&ctx.stream);
535	    let result = unsafe {
536	        ffi::fused_add_rms_norm_round_batched_cuda(
537	            h_ptr as *mut ffi::Half,
538	            r_ptr as *const ffi::Half,
539	            w_ptr as *const ffi::Half,
540	            o_ptr as *mut ffi::Half,
541	            hidden_dim as i32,
542	            seq_len as i32,
543	            eps,
544	            crate::tensor::active_cu_stream(ctx),
545	        )
546	    };
547	    result.result()?;
548	    Ok(())
549	}
